      whoA: '署名ポリシーが定めた人です。「全員の署名が必要」なら全共同署名者、「誰か1人の署名で可」なら1人、「M人中N人」ならその人数です。このルールを守らせるのはネットワークであって、このアプリではありません。満たさない取引はそのまま拒否されます。',
      keyQ: '共同署名者の鍵とは何で、自分のものはどこにありますか。',
      keyA: '公開アカウント鍵（CIP-1854）です。共有ウォレットを作る人に渡すと、支払いルールにあなたを含められます。それ自体では何も支払えず、あなたのウォレットへのアクセスを誰かに与えることもありません。あなたの各ウォレットは、「ウォレットを管理」→「自分の共同署名者の鍵」から自分のものを提供できます。',
      createQ: 'どうやって作りますか。',
      createA: '各参加者に共同署名者の鍵を求め（相手は自分のウォレットから送ります）、一覧に追加します。取引に必要な署名数を選んでウォレットを作成し、完成した構成情報を全員に送ってください。それを受け取るまで、鍵を渡した相手はウォレットを開けません。',
      spendQ: '支払いはどう進みますか。',
      spendA: '共同署名者の1人が取引を組み立てて署名し、メッセージで次の人に依頼します。取引全体が、それまでの署名とともにその中を移動します。ポリシーが満たされたら、手元に持っている人が送信を押します。最後の署名だけで自動的に送られることはありません。アプリはその時点で署名を求めるのをやめます。ポリシーを超える署名が1つ加わると、取引が自分の手数料を払いきれなくなり、拒否されるからです。',
      publishQ: 'チェーンへの公開は何をしますか。',
      publishA: 'ウォレットのスクリプトと参加者の名前を、取引のメタデータに記録します（CIP-146）。これにより、鍵が含まれている人なら誰でも、あとからチェーンでこのウォレットを見つけられます。通常の取引手数料がかかり、公開した人が負担します。新しい共有ウォレットには何も入っていないため、自分では払えません。',
      searchQ: 'チェーンの検索では何が見つかりますか。',
      searchA: 'あなたの鍵のいずれかを含む、公開済みの登録です。新しいスマートフォンや、まだそのウォレットに入っているか分からないときに役立ちます。ウォレットの存在と参加者は分かりますが、再構成はできません。登録に含まれるのはスクリプトであって、共同署名者の鍵ではないからです。参加者の誰かに構成情報を送ってもらってください。',
